class KIcon extends StatelessWidget {
  const KIcon(this.name, {super.key, this.size = 18, this.color});
  final String name;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final body = _icons[name];
    assert(body != null, 'KIcon: unknown icon "$name". Add its Lucide path to _icons.');
    if (body == null) return SizedBox(width: size, height: size);
    final c = color ?? DefaultTextStyle.of(context).style.color ?? const Color(0xFFFFFFFF);
    return SvgPicture.string(
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">$body</svg>',
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(c, BlendMode.srcIn),
    );
  }
}
